 private function project(array$input,array$deductions,array$decisions):array{$all=[];$objects=[];$total=0;$reservedTotal=0;$decisionMap=[];$reasonMap=[];foreach($decisions as$d){$decisionMap[$d['employeeId']]=$d['decision'];$reasonMap[$d['employeeId']]=(string)($d['reason']??'');}$reservePolicy=($input['recipientPolicyVersion']??null)==='reserved-shares-v1';foreach($input['objects']??[]as$o){$oid=(int)$o['objectId'];$gross=0;foreach($o['entitlements']??[]as$e)if(($e['active']??true)&&!$this->claimExists($e))$gross+=(int)$e['grossCents'];$kssBp=(int)($o['kssBp']??$o['deadlineBp']??10000);$deadline=intdiv($gross*max(0,10000-$kssBp)+5000,10000);$common=0;$personal=[];foreach($deductions as$d)if((int)$d['objectId']===$oid){if($d['employeeId']===null)$common+=(int)$d['amountCents'];else$personal[$d['employeeId']]=($personal[$d['employeeId']]??0)+(int)$d['amountCents'];}$pool=max(0,$gross-$deadline-$common);$excluded=[];foreach($o['recipients']??[]as$e){$eid=(string)$e['employeeId'];if(($decisionMap[$eid]??'pay')==='do_not_pay'||($reservePolicy&&($e['employment']??'unknown')!=='employed'))$excluded[]=$eid;}$originalAmounts=($o['recipients']??[])===[]?[]:OtizSettlementV2Math::allocate($pool,$o['recipients']??[],[],[]);if($reservePolicy){$preAmounts=$originalAmounts;$amounts=[];foreach($originalAmounts as$eid=>$amount)$amounts[$eid]=in_array((string)$eid,$excluded,true)?0:max(0,$amount-($personal[$eid]??0));}else{$preAmounts=($o['recipients']??[])===[]?[]:OtizSettlementV2Math::allocate($pool,$o['recipients']??[],$excluded,[]);$amounts=($o['recipients']??[])===[]?[]:OtizSettlementV2Math::allocate($pool,$o['recipients']??[],$excluded,$personal);}$objectReserved=0;foreach($o['recipients']??[]as$e){$eid=(string)$e['employeeId'];$reserved=$reservePolicy&&in_array($eid,$excluded,true)?max(0,($originalAmounts[$eid]??0)-($personal[$eid]??0)):0;$reason=$reserved>0?(($decisionMap[$eid]??'pay')==='do_not_pay'?($reasonMap[$eid]??''):(($e['employment']??'unknown')==='dismissed'?'Уволен