 private function assertReplacementManualFacts(int$id,array$input):void{$old=$this->row($id);if($old!==false&&isset($this->decode((string)$old['input_json'])['reserveRelease']))throw new \DomainException('RESERVE_RELEASE_REPLACEMENT_UNSUPPORTED');$byObject=[];$all=[];foreach($input['objects']??[]as$object)foreach($object['recipients']??[]as$recipient){$key=(string)$recipient['employeeId'];$byObject[(int)$object['objectId']][$key]=true;$all[$key]=true;}$deductions=$this->db->createCommand("SELECT object_id,employee_id FROM `{$this->prefix}fm2_otiz_deductions` WHERE calculation_id=:id AND active=1 AND employee_id IS NOT NULL",[':id'=>$id])->queryAll();foreach($deductions as$fact)if(!isset($byObject[(int)$fact['object_id']][(string)$fact['employee_id']]))throw new \DomainException('REPLACEMENT_MANUAL_FACT_CONFLICT');$decisions=$this->db->createCommand("SELECT employee_id FROM `{$this->prefix}fm2_otiz_payment_decisions` WHERE calculation_id=:id AND active=1",[':id'=>$id])->queryColumn();foreach($decisions as$employee)if(!isset($all[(string)$employee]))throw new \DomainException('REPLACEMENT_MANUAL_FACT_CONFLICT');}
